class Solution {
  public int minTime(String s, int[] order, int k) {
    int n = s.length();
    int[] when = new int[n];
    for (int t = 0; t < n; t++) when[order[t]] = t;
    long total = (long) n * (n + 1) / 2;
    if (total < k) return -1;
    int lo = 0, hi = n - 1;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      long bad = 0, run = 0;
      for (int i = 0; i < n; i++) {
        if (when[i] <= mid) {
          bad += run * (run + 1) / 2;
          run = 0;
        } else run++;
      }
      bad += run * (run + 1) / 2;
      if (total - bad >= k) hi = mid;
      else lo = mid + 1;
    }
    long bad = 0, run = 0;
    for (int i = 0; i < n; i++) {
      if (when[i] <= lo) {
        bad += run * (run + 1) / 2;
        run = 0;
      } else run++;
    }
    bad += run * (run + 1) / 2;
    return total - bad >= k ? lo : -1;
  }
}
